// SPA 单页应用的 SEO 元信息管理。
//
// 站点是客户端路由（GitHub Pages + BrowserRouter），静态 index.html 只有一份
// 默认 meta。路由切换后若不改写，所有页面会共用同一份 title/description，
// 对搜索引擎不友好。这里在路由变化时同步更新标题、描述、canonical 与社交卡片。

/** 站点正式域名，用于拼接 canonical / og:url 绝对地址 */
export const SITE_ORIGIN = "https://toast.coconot.cc";

export interface SeoMeta {
  title: string;
  description: string;
  /** 无需被索引的页面（支付结果页、404）置为 true */
  noindex?: boolean;
}

function upsertMeta(attr: "name" | "property", key: string, content: string) {
  let el = document.head.querySelector<HTMLMetaElement>(
    `meta[${attr}="${key}"]`,
  );
  if (!el) {
    el = document.createElement("meta");
    el.setAttribute(attr, key);
    document.head.appendChild(el);
  }
  el.setAttribute("content", content);
}

function upsertCanonical(href: string) {
  let el = document.head.querySelector<HTMLLinkElement>(
    'link[rel="canonical"]',
  );
  if (!el) {
    el = document.createElement("link");
    el.setAttribute("rel", "canonical");
    document.head.appendChild(el);
  }
  el.setAttribute("href", href);
}

/** 移除 canonical（noindex 页面不应再声明规范地址） */
function removeCanonical() {
  document.head.querySelector('link[rel="canonical"]')?.remove();
}

/** 按当前路由写入 SEO 元信息（title / description / robots / canonical / OG / Twitter） */
export function applySeo(meta: SeoMeta, pathname: string) {
  const url = SITE_ORIGIN + pathname;
  const robots = meta.noindex
    ? "noindex, follow"
    : "index, follow, max-image-preview:large";

  document.title = meta.title;
  upsertMeta("name", "description", meta.description);
  upsertMeta("name", "robots", robots);

  if (meta.noindex) {
    removeCanonical();
  } else {
    upsertCanonical(url);
  }

  upsertMeta("property", "og:title", meta.title);
  upsertMeta("property", "og:description", meta.description);
  upsertMeta("property", "og:url", url);
  upsertMeta("name", "twitter:title", meta.title);
  upsertMeta("name", "twitter:description", meta.description);
}
