import { useEffect, useRef, useState } from "react";
import {
  Routes,
  Route,
  useNavigate,
  useLocation,
  Link,
} from "react-router-dom";
import { useI18n, format } from "./i18n";
import { trackPageView } from "./lib/analytics";
import { applySeo, type SeoMeta } from "./lib/seo";
import LandingPage from "./pages/LandingPage";
import PreorderPage from "./pages/PreorderPage";
import ProQueryPage from "./pages/ProQueryPage";
import PayReturnPage from "./pages/PayReturnPage";
import ImapGuidePage from "./pages/ImapGuidePage";
import FeedbackPage from "./pages/FeedbackPage";
import FeedbackDetailPage from "./pages/FeedbackDetailPage";
import "./styles/variables.css";
import "./styles/base.css";
import "./styles/animations.css";
import "./components/Header.css";
import "./components/Hero.css";
import "./components/Features.css";
import "./components/FeatureShowcase.css";
import "./components/Download.css";
import "./components/Footer.css";

const NOT_FOUND_REDIRECT_SECONDS = 3;

function NotFound() {
  const { t } = useI18n();
  const navigate = useNavigate();
  const location = useLocation();
  const [seconds, setSeconds] = useState(NOT_FOUND_REDIRECT_SECONDS);

  useEffect(() => {
    const id = setInterval(() => {
      setSeconds((prev) => {
        if (prev <= 1) {
          clearInterval(id);
          navigate("/", { replace: true });
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(id);
  }, [navigate]);

  return (
    <main
      style={{
        minHeight: "calc(100vh - var(--header-height, 64px))",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        gap: "0.75rem",
        padding: "2rem",
        textAlign: "center",
      }}
    >
      <div
        style={{
          fontFamily: "var(--font-heading)",
          fontSize: "5rem",
          fontWeight: 700,
          lineHeight: 1,
          color: "var(--color-accent)",
        }}
      >
        {t.notFound.title}
      </div>
      <p style={{ fontSize: "1rem", color: "var(--color-text)" }}>
        {t.notFound.message}
      </p>
      <p style={{ fontSize: "0.875rem", color: "var(--color-text-muted)" }}>
        {format(t.notFound.redirecting, { seconds: String(seconds) })}
      </p>
      <p
        style={{
          fontSize: "0.8rem",
          color: "var(--color-text-muted)",
          wordBreak: "break-all",
          opacity: 0.7,
        }}
      >
        {location.pathname}
      </p>
      <Link
        to="/"
        style={{
          marginTop: "0.5rem",
          padding: "0.5rem 1.25rem",
          border: "1px solid var(--color-border)",
          borderRadius: "var(--radius-sm)",
          color: "var(--color-text)",
        }}
      >
        {t.notFound.back}
      </Link>
    </main>
  );
}

/** 监听路由变化并上报页面浏览（首次加载 + 每次 SPA 路由切换各上报一次） */
function RouteTracker() {
  const location = useLocation();
  // 幂等守卫：StrictMode 在开发模式下会挂载 effect 两次，若不做去重会重复上报。
  // 用 ref 记住上一次已上报的路径，同一路径只报一次；整页刷新会重新挂载组件、
  // ref 归零，因此真正的刷新仍会被正常计入一次。
  const lastReported = useRef<string | null>(null);

  useEffect(() => {
    const key = location.pathname + location.search;
    if (lastReported.current === key) return;
    lastReported.current = key;
    trackPageView(key, document.referrer);
  }, [location.pathname, location.search]);

  return null;
}

/** 路由或语言变化时同步各页面的 SEO 元信息（title / description / canonical / OG） */
function SeoManager() {
  const { t } = useI18n();
  const location = useLocation();

  useEffect(() => {
    const routeSeo: Record<string, SeoMeta> = {
      "/": t.seo.home,
      "/buy_pro": t.seo.buy,
      "/query_pro": t.seo.query,
      "/imap-guide": t.seo.imapGuide,
      "/feedback": t.seo.feedback,
      "/pay/result": { ...t.seo.payResult, noindex: true },
    };
    // 反馈详情页为动态路由，前缀匹配并置为 noindex
    const meta: SeoMeta = location.pathname.startsWith("/feedback/")
      ? { ...t.seo.feedbackDetail, noindex: true }
      : (routeSeo[location.pathname] ?? {
          title: `${t.notFound.title} — Coco Toast`,
          description: t.notFound.message,
          noindex: true,
        });
    applySeo(meta, location.pathname);
  }, [location.pathname, t]);

  return null;
}

export default function App() {
  return (
    <>
      <RouteTracker />
      <SeoManager />
      <Routes>
        <Route path="/" element={<LandingPage />} />
        <Route path="/buy_pro" element={<PreorderPage />} />
        <Route path="/query_pro" element={<ProQueryPage />} />
        <Route path="/pay/result" element={<PayReturnPage />} />
        <Route path="/imap-guide" element={<ImapGuidePage />} />
        <Route path="/feedback" element={<FeedbackPage />} />
        <Route path="/feedback/:id" element={<FeedbackDetailPage />} />
        <Route path="*" element={<NotFound />} />
      </Routes>
    </>
  );
}
