// 意见反馈相关 API 客户端：提交反馈、查看反馈、附件前端校验。
// 基址见 lib/apiBase.ts（构建时可用 VITE_API_BASE_URL 覆盖）。
//
// 提交走 multipart/form-data：文本字段名与后端契约一一对应，
// 文件按 file0 / file1 / file2 追加（最多 3 个）。
// 无论填写多少引导项，最终都组装成一段文本 content 落库。

import { API_BASE_URL } from "./apiBase";
import { getVisitorId } from "./analytics";

/** 反馈类型：提意见 / 提 Bug / 付款·售后 */
export type FeedbackKind = "suggestion" | "bug" | "payment";

/** 提交反馈的载荷（字段名即后端表单字段名，除 files 外） */
export interface FeedbackSubmitPayload {
  /** 必填：反馈正文（bug 模式由引导字段组装；suggestion/payment 用文本框内容） */
  content: string;
  kind?: FeedbackKind;
  /** 系统信息（引导模式可填，也可由 URL 参数预填） */
  system_info?: string;
  /** 应用版本（同上） */
  app_version?: string;
  /** 联系方式；kind=payment 时必填 */
  contact?: string;
  /** 待上传文件（最多 3 个） */
  files?: File[];
}

/** 提交成功返回的 data */
export interface FeedbackSubmitResult {
  id: string;
  url: string;
}

/** 附件信息（url 为 R2 公开直链） */
export interface FeedbackAttachment {
  name: string;
  size: number;
  key: string;
  url: string;
}

/** GET /api/feedback/:id 返回的 data */
export interface FeedbackData {
  id: string;
  /** Unix 秒 */
  created_at: number | null;
  kind: string | null;
  content: string;
  system_info: string | null;
  app_version: string | null;
  contact: string | null;
  attachments: FeedbackAttachment[];
  reply: string | null;
  /** Unix 秒 */
  replied_at: number | null;
}

/** 反馈不存在时抛此错误，便于调用方区分 404。 */
export class FeedbackNotFoundError extends Error {
  constructor() {
    super("FEEDBACK_NOT_FOUND");
    this.name = "FeedbackNotFoundError";
  }
}

/**
 * 提交一条反馈（POST /api/feedback，multipart/form-data）。
 * 返回 { id, url }；请求失败或 success=false 时抛错。
 */
export async function submitFeedback(
  payload: FeedbackSubmitPayload,
): Promise<FeedbackSubmitResult> {
  const form = new FormData();
  form.append("content", payload.content);

  // 仅追加有值的文本字段，避免把空串当成有效值提交
  const put = (key: string, value: string | undefined) => {
    if (value != null && value.trim() !== "") form.append(key, value);
  };
  put("kind", payload.kind);
  put("system_info", payload.system_info);
  put("app_version", payload.app_version);
  put("contact", payload.contact);

  // 匿名访客 id（复用官网埋点同款 vid）
  const vid = getVisitorId();
  if (vid) form.append("vid", vid);

  (payload.files ?? [])
    .slice(0, MAX_FEEDBACK_FILES)
    .forEach((file, i) => form.append(`file${i}`, file));

  const res = await fetch(`${API_BASE_URL}/api/feedback`, {
    method: "POST",
    body: form,
  });
  const body = (await res.json().catch(() => null)) as {
    success?: boolean;
    message?: string;
    data?: FeedbackSubmitResult;
  } | null;
  if (!res.ok || !body?.success || !body.data) {
    throw new Error(body?.message || `提交失败 (HTTP ${res.status})`);
  }
  return body.data;
}

/**
 * 查看一条反馈（GET /api/feedback/:id）。
 * 404 时抛 FeedbackNotFoundError，其余失败抛普通 Error。
 */
export async function fetchFeedback(id: string): Promise<FeedbackData> {
  const res = await fetch(
    `${API_BASE_URL}/api/feedback/${encodeURIComponent(id)}`,
  );
  if (res.status === 404) {
    throw new FeedbackNotFoundError();
  }
  const body = (await res.json().catch(() => null)) as {
    success?: boolean;
    message?: string;
    data?: FeedbackData;
  } | null;
  if (!res.ok || !body?.success || !body.data) {
    throw new Error(body?.message || `加载失败 (HTTP ${res.status})`);
  }
  return body.data;
}

/* ------------------------------------------------------------------ */
/* 附件前端校验                                                        */
/* ------------------------------------------------------------------ */

/** 最多上传文件数 */
export const MAX_FEEDBACK_FILES = 3;
/** 所有文件总大小上限（10MB） */
export const MAX_FEEDBACK_TOTAL_BYTES = 10 * 1024 * 1024;
/** 允许的扩展名白名单（小写，不含点） */
export const FEEDBACK_ALLOWED_EXT = [
  "txt",
  "log",
  "json",
  "zip",
  "png",
  "jpg",
  "jpeg",
  "gif",
  "pdf",
  "dmg",
  "csv",
] as const;

/** 附件校验失败原因 */
export type FeedbackFileError =
  | { code: "too_many"; max: number }
  | { code: "total_size"; maxBytes: number }
  | { code: "ext"; ext: string };

export interface FeedbackFileValidation {
  ok: boolean;
  error?: FeedbackFileError;
}

/** 取文件扩展名（小写，不含点；无扩展名返回空串） */
export function fileExt(name: string): string {
  const dot = name.lastIndexOf(".");
  if (dot <= 0 || dot === name.length - 1) return "";
  return name.slice(dot + 1).toLowerCase();
}

/**
 * 校验待上传附件：数量上限、总大小上限、扩展名白名单。
 * 返回校验结果，页面据此给出 i18n 友好提示。
 */
export function validateFeedbackFiles(files: File[]): FeedbackFileValidation {
  if (files.length > MAX_FEEDBACK_FILES) {
    return { ok: false, error: { code: "too_many", max: MAX_FEEDBACK_FILES } };
  }
  const total = files.reduce((sum, f) => sum + f.size, 0);
  if (total > MAX_FEEDBACK_TOTAL_BYTES) {
    return {
      ok: false,
      error: { code: "total_size", maxBytes: MAX_FEEDBACK_TOTAL_BYTES },
    };
  }
  for (const f of files) {
    const ext = fileExt(f.name);
    if (!(FEEDBACK_ALLOWED_EXT as readonly string[]).includes(ext)) {
      return { ok: false, error: { code: "ext", ext } };
    }
  }
  return { ok: true };
}