import {
  useEffect,
  useMemo,
  useState,
  type ChangeEvent,
  type FormEvent,
} from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useI18n, format } from "../i18n";
import PaymentLayout from "../components/PaymentLayout";
import {
  submitFeedback,
  validateFeedbackFiles,
  type FeedbackKind,
  type FeedbackFileError,
} from "../lib/feedbackApi";
import { formatFileSize } from "../lib/downloadApi";
import { detectOS } from "../utils/detectOS";
import "./FeedbackPage.css";

/** 反馈类型选项（顺序即展示顺序）：提意见 / 提 Bug / 付款·售后 */
const KINDS: FeedbackKind[] = ["suggestion", "bug", "payment"];

type Status = "idle" | "submitting" | "error";
/** 日志位置覆盖的三个系统（展示顺序：当前系统 → macOS → Windows → Linux） */
type LogOS = "macos" | "windows" | "linux";

const ALL_LOG_OS: LogOS[] = ["macos", "windows", "linux"];
const LOG_OS_LABELS: Record<LogOS, string> = {
  macos: "macOS",
  windows: "Windows",
  linux: "Linux",
};

export default function FeedbackPage() {
  const { t } = useI18n();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const os = useMemo(detectOS, []);

  const [kind, setKind] = useState<FeedbackKind>("suggestion");
  // 提意见 / 付款·售后：文本框内容
  const [suggestionText, setSuggestionText] = useState("");
  const [paymentText, setPaymentText] = useState("");
  // 提 Bug：引导字段（顺序：操作了什么 / 发生了什么 / 应该如何 / 补充说明）
  const [input, setInput] = useState("");
  const [actual, setActual] = useState("");
  const [expected, setExpected] = useState("");
  const [otherIssue, setOtherIssue] = useState("");
  // 系统 / 版本：bug 模式可填；suggestion/payment 仅在 URL 预填时静默提交
  const [system, setSystem] = useState("");
  const [version, setVersion] = useState("");
  // 付款·售后：邮箱必填
  const [contact, setContact] = useState("");

  const [files, setFiles] = useState<File[]>([]);
  const [fileError, setFileError] = useState<string | null>(null);

  const [status, setStatus] = useState<Status>("idle");
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  // 日志位置：默认收起，展开后按「当前系统 → macOS → Windows → Linux」列出
  const [logOpen, setLogOpen] = useState(false);
  const [copiedPath, setCopiedPath] = useState<LogOS | null>(null);

  // URL 参数预填（供桌面端跳转）：kind / system / version
  useEffect(() => {
    const k = searchParams.get("kind");
    if (k === "bug" || k === "suggestion" || k === "payment") setKind(k);
    const sys = searchParams.get("system");
    const ver = searchParams.get("version");
    if (sys) setSystem(sys);
    if (ver) setVersion(ver);
  }, [searchParams]);

  const kindLabelOf = (k: FeedbackKind) =>
    k === "suggestion"
      ? t.feedback.kindSuggestion
      : k === "bug"
        ? t.feedback.kindBug
        : t.feedback.kindPayment;

  const describeFileError = (error: FeedbackFileError): string => {
    if (error.code === "ext") {
      return format(t.feedback.errorExt, { ext: error.ext || "?" });
    }
    if (error.code === "too_many") return t.feedback.errorTooManyFiles;
    return t.feedback.errorTotalSize;
  };

  const onFilesSelected = (e: ChangeEvent<HTMLInputElement>) => {
    const picked = Array.from(e.target.files ?? []);
    e.target.value = "";
    if (picked.length === 0) return;
    const candidate = [...files, ...picked];
    const res = validateFeedbackFiles(candidate);
    if (!res.ok) {
      if (res.error) setFileError(describeFileError(res.error));
      return;
    }
    setFileError(null);
    setFiles(candidate);
  };

  const removeFile = (index: number) => {
    setFiles((prev) => prev.filter((_, i) => i !== index));
    setFileError(null);
  };

  /** 提 Bug：把引导字段组装成带小标题的多行文本（空的引导项整行省略） */
  const buildBugContent = (): string => {
    const lines: string[] = [];
    const push = (label: string, value: string) => {
      const v = value.trim();
      if (v) lines.push(`【${label}】${v}`);
    };
    push(t.feedback.contentInput, input);
    push(t.feedback.contentActual, actual);
    push(t.feedback.contentExpected, expected);
    push(t.feedback.contentOther, otherIssue);
    return lines.join("\n");
  };

  const totalSize = files.reduce((sum, f) => sum + f.size, 0);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (status === "submitting") return;

    // 按类型组装修正后的 content
    let content = "";
    if (kind === "suggestion") {
      content = suggestionText.trim();
    } else if (kind === "payment") {
      content = paymentText.trim();
    } else {
      const hasAny =
        input.trim() !== "" ||
        actual.trim() !== "" ||
        expected.trim() !== "" ||
        otherIssue.trim() !== "";
      content = hasAny ? buildBugContent() : "";
    }

    if (!content) {
      setErrorMsg(t.feedback.errorContentRequired);
      setStatus("error");
      return;
    }

    // 付款·售后：邮箱必填
    if (kind === "payment" && !contact.trim()) {
      setErrorMsg(t.feedback.errorEmailRequired);
      setStatus("error");
      return;
    }

    setErrorMsg(null);
    setStatus("submitting");
    try {
      const data = await submitFeedback({
        content,
        kind,
        system_info: system.trim() || undefined,
        app_version: version.trim() || undefined,
        contact: contact.trim() || undefined,
        files,
      });
      // 提交成功后直接进入反馈详情页，由详情页提示保存 / 复制本页链接
      navigate(`/feedback/${data.id}`, { replace: true });
    } catch (err) {
      setStatus("error");
      setErrorMsg(err instanceof Error ? err.message : String(err));
    }
  };

  const copyLogPath = (system: LogOS, value: string) => {
    navigator.clipboard
      ?.writeText(value)
      .then(() => {
        setCopiedPath(system);
        window.setTimeout(() => setCopiedPath(null), 1600);
      })
      .catch(() => {});
  };

  // 日志位置列表：当前系统排最前，其余按 macOS → Windows → Linux 补全（不重复）
  const logPaths = useMemo(() => {
    const current: LogOS = os === "windows" || os === "linux" ? os : "macos";
    const paths: Record<LogOS, string> = {
      macos: t.feedback.logPathMacos,
      windows: t.feedback.logPathWin,
      linux: t.feedback.logPathLinux,
    };
    const order: LogOS[] = [current, ...ALL_LOG_OS.filter((s) => s !== current)];
    return order.map((system) => ({
      system,
      label: LOG_OS_LABELS[system],
      path: paths[system],
    }));
  }, [os, t]);

  return (
    <PaymentLayout>
      <div className="feedback">
        <form className="feedback__form" onSubmit={handleSubmit}>
          <header className="feedback__head">
            <span className="feedback__badge">{t.feedback.badge}</span>
            <h1 className="feedback__title">{t.feedback.title}</h1>
            <p className="feedback__subtitle">{t.feedback.subtitle}</p>
          </header>

          {/* 类型：提意见 / 提 Bug / 付款·售后 */}
          <div className="feedback__field">
            <span className="feedback__label">{t.feedback.kindLabel}</span>
            <div className="feedback__chips">
              {KINDS.map((k) => (
                <button
                  key={k}
                  type="button"
                  className={
                    "feedback__chip" + (kind === k ? " is-active" : "")
                  }
                  aria-pressed={kind === k}
                  onClick={() => setKind(k)}
                >
                  {kindLabelOf(k)}
                </button>
              ))}
            </div>
          </div>

          {/* 提意见：仅一个文本框 */}
          {kind === "suggestion" && (
            <div className="feedback__field">
              <label className="feedback__label" htmlFor="fb-suggestion">
                {t.feedback.suggestionLabel}
              </label>
              <textarea
                id="fb-suggestion"
                className="feedback__textarea"
                rows={5}
                placeholder={t.feedback.suggestionPlaceholder}
                value={suggestionText}
                onChange={(e) => setSuggestionText(e.target.value)}
              />
              <p className="feedback__hint">{t.feedback.suggestionHint}</p>
            </div>
          )}

          {/* 提 Bug：引导字段 + 可选系统/版本 + 可选补充说明 */}
          {kind === "bug" && (
            <div className="feedback__fields">
              <div className="feedback__field">
                <label className="feedback__label" htmlFor="fb-input">
                  {t.feedback.bugInputLabel}
                </label>
                <textarea
                  id="fb-input"
                  className="feedback__textarea is-sm"
                  rows={2}
                  placeholder={t.feedback.bugInputPlaceholder}
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                />
              </div>

              <div className="feedback__field">
                <label className="feedback__label" htmlFor="fb-actual">
                  {t.feedback.bugActualLabel}
                </label>
                <textarea
                  id="fb-actual"
                  className="feedback__textarea is-sm"
                  rows={2}
                  placeholder={t.feedback.bugActualPlaceholder}
                  value={actual}
                  onChange={(e) => setActual(e.target.value)}
                />
              </div>

              <div className="feedback__field">
                <label className="feedback__label" htmlFor="fb-expected">
                  {t.feedback.bugExpectedLabel}
                </label>
                <textarea
                  id="fb-expected"
                  className="feedback__textarea is-sm"
                  rows={2}
                  placeholder={t.feedback.bugExpectedPlaceholder}
                  value={expected}
                  onChange={(e) => setExpected(e.target.value)}
                />
              </div>

              <div className="feedback__row">
                <div className="feedback__field">
                  <label className="feedback__label" htmlFor="fb-system">
                    {t.feedback.bugSystemLabel}
                  </label>
                  <input
                    id="fb-system"
                    className="feedback__input"
                    type="text"
                    placeholder={t.feedback.bugSystemPlaceholder}
                    value={system}
                    onChange={(e) => setSystem(e.target.value)}
                  />
                </div>
                <div className="feedback__field">
                  <label className="feedback__label" htmlFor="fb-version">
                    {t.feedback.bugVersionLabel}
                  </label>
                  <input
                    id="fb-version"
                    className="feedback__input"
                    type="text"
                    placeholder={t.feedback.bugVersionPlaceholder}
                    value={version}
                    onChange={(e) => setVersion(e.target.value)}
                  />
                </div>
              </div>

              <div className="feedback__field">
                <label className="feedback__label" htmlFor="fb-other">
                  {t.feedback.bugOtherLabel}
                </label>
                <textarea
                  id="fb-other"
                  className="feedback__textarea is-sm"
                  rows={2}
                  placeholder={t.feedback.bugOtherPlaceholder}
                  value={otherIssue}
                  onChange={(e) => setOtherIssue(e.target.value)}
                />
              </div>
            </div>
          )}

          {/* 付款·售后：文本框 + 邮箱必填 */}
          {kind === "payment" && (
            <div className="feedback__fields">
              <div className="feedback__field">
                <label className="feedback__label" htmlFor="fb-payment">
                  {t.feedback.paymentLabel}
                </label>
                <textarea
                  id="fb-payment"
                  className="feedback__textarea"
                  rows={4}
                  placeholder={t.feedback.paymentPlaceholder}
                  value={paymentText}
                  onChange={(e) => setPaymentText(e.target.value)}
                />
              </div>
              <div className="feedback__field">
                <label className="feedback__label" htmlFor="fb-contact">
                  {t.feedback.paymentEmailLabel}
                </label>
                <input
                  id="fb-contact"
                  className="feedback__input"
                  type="email"
                  placeholder={t.feedback.paymentEmailPlaceholder}
                  value={contact}
                  onChange={(e) => setContact(e.target.value)}
                />
                <p className="feedback__hint">{t.feedback.paymentEmailHint}</p>
              </div>
            </div>
          )}

          {/* 提意见 / 提 Bug：可选联系方式 */}
          {(kind === "suggestion" || kind === "bug") && (
            <div className="feedback__field">
              <label className="feedback__label" htmlFor="fb-contact">
                {t.feedback.contactLabel}
              </label>
              <input
                id="fb-contact"
                className="feedback__input"
                type="text"
                placeholder={t.feedback.contactPlaceholder}
                value={contact}
                onChange={(e) => setContact(e.target.value)}
              />
            </div>
          )}

          {/* 附件（三种类型通用） */}
          <div className="feedback__field">
            <span className="feedback__label">
              {t.feedback.attachmentsLabel}
            </span>
            <div className="feedback__file-row">
              <label className="feedback__file-btn">
                <input type="file" multiple hidden onChange={onFilesSelected} />
                {t.feedback.addFile}
              </label>
              <span className="feedback__file-meta">
                {files.length > 0
                  ? format(t.feedback.filesSelected, {
                      count: String(files.length),
                      size: formatFileSize(totalSize),
                    })
                  : t.feedback.attachmentsHint}
              </span>
            </div>
            <p className="feedback__hint">
              {t.feedback.attachmentsHint} · {t.feedback.attachmentsAllowed}
            </p>
            {files.length > 0 && (
              <ul className="feedback__file-list">
                {files.map((f, i) => (
                  <li className="feedback__file-item" key={`${f.name}-${i}`}>
                    <span className="feedback__file-name">{f.name}</span>
                    <span className="feedback__file-size">
                      {formatFileSize(f.size)}
                    </span>
                    <button
                      type="button"
                      className="feedback__file-remove"
                      onClick={() => removeFile(i)}
                      aria-label={t.feedback.removeFile}
                    >
                      ×
                    </button>
                  </li>
                ))}
              </ul>
            )}
            {fileError && <p className="feedback__error">{fileError}</p>}

            {/* 日志引导 */}
            <div className="feedback__log">
              <span className="feedback__log-title">{t.feedback.logTitle}</span>
              <p className="feedback__log-text">{t.feedback.logHint}</p>
              <button
                type="button"
                className="feedback__log-toggle"
                aria-expanded={logOpen}
                onClick={() => setLogOpen((open) => !open)}
              >
                {t.feedback.logLocation}
              </button>
              {logOpen && (
                <ul className="feedback__log-list">
                  {logPaths.map((item) => (
                    <li className="feedback__log-item" key={item.system}>
                      <span className="feedback__log-os">{item.label}</span>
                      <code className="feedback__log-path">{item.path}</code>
                      <button
                        type="button"
                        className="feedback__log-copy"
                        onClick={() => copyLogPath(item.system, item.path)}
                      >
                        {copiedPath === item.system
                          ? t.feedback.copied
                          : t.feedback.copy}
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>

          {status === "error" && errorMsg && (
            <div className="feedback__notice" role="alert">
              <p className="feedback__notice-title">{t.feedback.errorTitle}</p>
              <p className="feedback__notice-text">{errorMsg}</p>
            </div>
          )}

          <button
            type="submit"
            className="feedback__submit"
            disabled={status === "submitting"}
          >
            {status === "submitting"
              ? t.feedback.submitting
              : t.feedback.submit}
          </button>
        </form>
      </div>
    </PaymentLayout>
  );
}
