/**
 * 支付渠道品牌图标（内联 SVG，fill: currentColor，颜色由外层 CSS 控制）。
 * 路径数据来自 simple-icons v13（CC0），viewBox 统一为 0 0 24 24。
 */

interface BrandIconProps {
  className?: string;
}

function BrandIcon({
  className,
  d,
  title,
  viewBox = '0 0 24 24',
}: BrandIconProps & { d: string; title: string; viewBox?: string }) {
  return (
    <svg
      className={className}
      viewBox={viewBox}
      role="img"
      aria-label={title}
      fill="currentColor"
    >
      <title>{title}</title>
      <path d={d} />
    </svg>
  );
}

