import { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { useI18n, format } from "../i18n";
import PaymentLayout from "../components/PaymentLayout";
import {
  fetchFeedback,
  FeedbackNotFoundError,
  type FeedbackData,
} from "../lib/feedbackApi";
import { formatFileSize } from "../lib/downloadApi";
import "./FeedbackPage.css";
import "./FeedbackDetailPage.css";

type Status = "loading" | "ok" | "notfound" | "error";

/** Unix 秒 → 本地时间字符串 */
function formatTime(seconds: number | null): string | null {
  if (seconds == null) return null;
  return new Date(seconds * 1000).toLocaleString();
}

/** 有值才渲染的结构化字段 */
function Field({ label, value }: { label: string; value: string | null }) {
  if (value == null || value.trim() === "") return null;
  return (
    <div className="feedback__detail-item">
      <span className="feedback__detail-label">{label}</span>
      <div className="feedback__detail-value">{value}</div>
    </div>
  );
}

export default function FeedbackDetailPage() {
  const { t } = useI18n();
  const { id } = useParams<{ id: string }>();

  const [status, setStatus] = useState<Status>("loading");
  const [data, setData] = useState<FeedbackData | null>(null);
  const [retryKey, setRetryKey] = useState(0);
  const [copied, setCopied] = useState(false);

  // 分享链接取当前页面域名（后端返回的 url 指向线上域名，本地 / 预览环境下不可用）
  const shareUrl = `${window.location.origin}${window.location.pathname}`;

  const copyShareUrl = () => {
    navigator.clipboard
      ?.writeText(shareUrl)
      .then(() => {
        setCopied(true);
        window.setTimeout(() => setCopied(false), 1600);
      })
      .catch(() => {});
  };

  useEffect(() => {
    if (!id) {
      setStatus("notfound");
      return;
    }
    let cancelled = false;
    setStatus("loading");
    fetchFeedback(id)
      .then((d) => {
        if (cancelled) return;
        setData(d);
        setStatus("ok");
      })
      .catch((e) => {
        if (cancelled) return;
        setStatus(e instanceof FeedbackNotFoundError ? "notfound" : "error");
      });
    return () => {
      cancelled = true;
    };
  }, [id, retryKey]);

  const kindLabel = (k: string | null): string | null => {
    if (k === "bug") return t.feedback.kindBug;
    if (k === "suggestion") return t.feedback.kindSuggestion;
    if (k === "payment") return t.feedback.kindPayment;
    return k;
  };

  return (
    <PaymentLayout>
      <div className="feedback__detail">
        <header className="feedback__head">
          <span className="feedback__badge">{t.feedback.title}</span>
        </header>

        {status === "loading" && (
          <div className="feedback__state" role="status">
            <span className="feedback__spinner" aria-hidden="true" />
            <p className="feedback__state-meta">{t.feedback.detailLoading}</p>
          </div>
        )}

        {status === "notfound" && (
          <div className="feedback__state is-error" role="alert">
            <p className="feedback__state-title">
              {t.feedback.detailNotFoundTitle}
            </p>
            <p className="feedback__state-meta">
              {t.feedback.detailNotFoundHint}
            </p>
          </div>
        )}

        {status === "error" && (
          <div className="feedback__state is-error" role="alert">
            <p className="feedback__state-title">
              {t.feedback.detailErrorTitle}
            </p>
            <p className="feedback__state-meta">{t.feedback.detailErrorHint}</p>
            <button
              type="button"
              className="feedback__state-btn"
              onClick={() => setRetryKey((k) => k + 1)}
            >
              {t.feedback.detailRetry}
            </button>
          </div>
        )}

        {status === "ok" && data && (
          <>
            <div className="feedback__detail-content">{data.content}</div>

            {data.attachments.length > 0 && (
              <div>
                <h2 className="feedback__detail-section-title">
                  {t.feedback.detailAttachments}
                </h2>
                <ul className="feedback__attach-list">
                  {data.attachments.map((att, i) => (
                    <li
                      className="feedback__attach-item"
                      key={`${att.key}-${i}`}
                    >
                      <a
                        className="feedback__attach-name"
                        href={att.url}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        {att.name}
                      </a>
                      <span className="feedback__attach-size">
                        {formatFileSize(att.size)}
                      </span>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            <div className="feedback__detail-list">
              <Field
                label={t.feedback.detailKindLabel}
                value={kindLabel(data.kind)}
              />
              <Field
                label={t.feedback.detailCreatedAt}
                value={formatTime(data.created_at)}
              />
              <Field label={t.feedback.detailId} value={id} />
              <Field label={t.feedback.detailSystem} value={data.system_info} />
              <Field
                label={t.feedback.detailVersion}
                value={data.app_version}
              />
              <Field label={t.feedback.detailContact} value={data.contact} />
            </div>

            <div>
              <h2 className="feedback__detail-section-title">
                {t.feedback.detailReply}
              </h2>
              {data.reply ? (
                <div className="feedback__reply">
                  {formatTime(data.replied_at) && (
                    <span className="feedback__reply-time">
                      {format(t.feedback.detailReplyAt, {
                        time: formatTime(data.replied_at) as string,
                      })}
                    </span>
                  )}
                  <p className="feedback__reply-text">{data.reply}</p>
                </div>
              ) : (
                <p className="feedback__reply-empty">
                  {t.feedback.detailNoReply}
                </p>
              )}
            </div>

            {/* 页面底部：提示保存 / 复制本页链接，便于日后回来查看回复 */}
            <div className="feedback__share">
              <p className="feedback__share-text">{t.feedback.successHint}</p>
              <button
                type="button"
                className="feedback__btn feedback__btn--primary"
                onClick={copyShareUrl}
              >
                {copied ? t.feedback.copied : t.feedback.copyLink}
              </button>
            </div>
          </>
        )}

        <Link to="/feedback" className="feedback__back-link">
          {t.feedback.detailBack}
        </Link>
      </div>
    </PaymentLayout>
  );
}
